// Minimal rules engine (gateway pattern: rules first, AI as fallback).
// Simplified trigger input: { message, sessionId, isFirstTurn, hasHumanAgent, contact, inputs, ... }
const e = $input.first().json;
const texto = String(e.message || '').toLowerCase();
const has = (palabras) => palabras.some((p) => texto.includes(p));

const TYPES = ['sendText','sendImage','sendFile','addTag','userDelegate','teamDelegate','addVar','setVar','input','updateContact'];
let actions = [];

if (e.isFirstTurn) {
	actions = [
		{ type: 'sendText', text: `Hello${e.contact?.nombre ? ' ' + e.contact.nombre : ''}! I am the virtual assistant. How can I help you?` },
	];
} else if (has(['human', 'advisor', 'agent', 'person'])) {
	actions = [
		{ type: 'sendText', text: 'Sure, let me transfer you to our team.' },
		{ type: 'teamDelegate', id_team: 0 }, // ← your team ID (Team · Get Many)
	];
} else if (has(['price', 'cost', 'quote', 'buy', 'plan'])) {
	actions = [
		{ type: 'sendText', text: 'Sure, I can help you with pricing. Which product or plan are you interested in?' },
		{ type: 'addVar', varname: 'intencion', varvalue: 'precio' },
	];
} else {
	// Fallback (you can plug the output of an AI Agent in here)
	actions = [{ type: 'sendText', text: 'Tell me a bit more so I can help you.' }];
}

// Sanitize: valid types only, never empty.
actions = actions.filter((a) => a && TYPES.includes(a.type));
if (actions.length === 0) {
	actions = [{ type: 'sendText', text: 'I could not process your request, please give me more details.' }];
}

// CRITICAL: closing input unless delegating (without input, LiveConnect exits the callback).
const delega = actions.some((a) => a.type === 'userDelegate' || a.type === 'teamDelegate');
if (!delega && !actions.some((a) => a.type === 'input')) {
	actions.push({ type: 'input', input: '' });
}

// Mandatory apiResp envelope: actions ALWAYS under data.
return [{ json: { status: 1, status_message: 'Ok', data: { actions } } }];
